    35  static void
    36  _add_gid_and_children (const OT::glyf::accelerator_t &glyf,
    37                         hb_codepoint_t gid,
    38                         hb_set_t *gids_to_retain)
    39  {
    40    if (hb_set_has (gids_to_retain, gid))
    41      // Already visited this gid, ignore.
    42      return;
    43
    44    hb_set_add (gids_to_retain, gid);
    45
    46    OT::glyf::CompositeGlyphHeader::Iterator composite;
    47    if (glyf.get_composite (gid, &composite))
    48    {
    49      do
    50      {
    51        _add_gid_and_children (glyf, (hb_codepoint_t) composite.current->glyphIndex, gids_to_retain);
    52      } while (composite.move_to_next());
    53    }
    54  }
    55
    56  static void
    57  _gsub_closure (hb_face_t *face, hb_set_t *gids_to_retain)
    58  {
    59    hb_auto_t<hb_set_t> lookup_indices;
    60    hb_ot_layout_collect_lookups (face,
    61                                  HB_OT_TAG_GSUB,
    62                                  nullptr,
    63                                  nullptr,
    64                                  nullptr,
    65                                  &lookup_indices);
    66    hb_ot_layout_lookups_substitute_closure (face,
    67                                             &lookup_indices,
    68                                             gids_to_retain);
    69  }
    70
    71
    72  static void
    73  _populate_gids_to_retain (hb_face_t *face,
    74                            const hb_set_t *unicodes,
    75                            bool close_over_gsub,
    76                            hb_set_t *unicodes_to_retain,
    77                            hb_map_t *codepoint_to_glyph,
    78                            hb_vector_t<hb_codepoint_t> *glyphs)
    79  {
    80    OT::cmap::accelerator_t cmap;
    81    OT::glyf::accelerator_t glyf;
    82    cmap.init (face);
    83    glyf.init (face);
    84
    85    hb_set_t *initial_gids_to_retain = hb_set_create ();
    86    initial_gids_to_retain->add (0); // Not-def
    87
    88    hb_codepoint_t cp = HB_SET_VALUE_INVALID;
    89    while (unicodes->next (&cp))
    90    {
    91      hb_codepoint_t gid;
    92      if (!cmap.get_nominal_glyph (cp, &gid))
    93      {
    94        DEBUG_MSG(SUBSET, nullptr, "Drop U+%04X; no gid", cp);
    95        continue;
    96      }
    97      unicodes_to_retain->add (cp);
    98      codepoint_to_glyph->set (cp, gid);
    99      initial_gids_to_retain->add (gid);
   100    }
   101
   102    if (close_over_gsub)
   103      // Add all glyphs needed for GSUB substitutions.
   104      _gsub_closure (face, initial_gids_to_retain);
   105
   106    // Populate a full set of glyphs to retain by adding all referenced
   107    // composite glyphs.
   108    hb_codepoint_t gid = HB_SET_VALUE_INVALID;
   109    hb_set_t *all_gids_to_retain = hb_set_create ();
   110    while (initial_gids_to_retain->next (&gid))
   111    {
   112      _add_gid_and_children (glyf, gid, all_gids_to_retain);
   113    }
   114    hb_set_destroy (initial_gids_to_retain);
   115
   116    glyphs->alloc (all_gids_to_retain->get_population ());
   117    gid = HB_SET_VALUE_INVALID;
   118    while (all_gids_to_retain->next (&gid))
   119      glyphs->push (gid);
   120
   121    hb_set_destroy (all_gids_to_retain);
   122    glyf.fini ();
   123    cmap.fini ();
   124  }
