   126  static void
   127  _create_old_gid_to_new_gid_map (const hb_vector_t<hb_codepoint_t> &glyphs,
   128                                  hb_map_t *glyph_map)
   129  {
   130    for (unsigned int i = 0; i < glyphs.len; i++) {
   131      glyph_map->set (glyphs[i], i);
   132    }
   133  }
