   135  /**
   136   * hb_subset_plan_create:
   137   * Computes a plan for subsetting the supplied face according
   138   * to a provide profile and input. The plan describes
   139   * which tables and glyphs should be retained.
   140   *
   141   * Return value: New subset plan.
   142   *
   143   * Since: 1.7.5
   144   **/
   145  hb_subset_plan_t *
   146  hb_subset_plan_create (hb_face_t           *face,
   147                         hb_subset_profile_t *profile,
   148                         hb_subset_input_t   *input)
   149  {
   150    hb_subset_plan_t *plan = hb_object_create<hb_subset_plan_t> ();
   151
   152    plan->drop_hints = input->drop_hints;
   153    plan->drop_ot_layout = input->drop_ot_layout;
   154    plan->unicodes = hb_set_create();
   155    plan->glyphs.init();
   156    plan->source = hb_face_reference (face);
   157    plan->dest = hb_face_builder_create ();
   158    plan->codepoint_to_glyph = hb_map_create();
   159    plan->glyph_map = hb_map_create();
   160
   161    _populate_gids_to_retain (face,
   162                              input->unicodes,
   163                              !plan->drop_ot_layout,
   164                              plan->unicodes,
   165                              plan->codepoint_to_glyph,
   166                              &plan->glyphs);
   167    _create_old_gid_to_new_gid_map (plan->glyphs,
   168                                    plan->glyph_map);
   169
   170    return plan;
   171  }
   172
   173  /**
   174   * hb_subset_plan_destroy:
   175   *
   176   * Since: 1.7.5
   177   **/
   178  void
   179  hb_subset_plan_destroy (hb_subset_plan_t *plan)
   180  {
   181    if (!hb_object_destroy (plan)) return;
   182
   183    hb_set_destroy (plan->unicodes);
   184    plan->glyphs.fini();
   185    hb_face_destroy (plan->source);
   186    hb_face_destroy (plan->dest);
   187    hb_map_destroy (plan->codepoint_to_glyph);
   188    hb_map_destroy (plan->glyph_map);
   189
   190    free (plan);
   191  }
